export default defineConfig({
  testDir: './tests', fullyParallel: true, retries: process.env.CI ? 2 : 0,
  use: { baseURL: 'http://127.0.0.1:3000', trace: 'on-first-retry' },
  projects: [{ name: 'chromium', use: devices['Desktop Chrome'] }],
  webServer: { command: 'npm run dev', url: 'http://127.0.0.1:3000', reuseExistingServer: !process.env.CI },
});

export const test = base.extend<{ checkout: CheckoutPage }>({
  checkout: async ({ page }, use) => { await use(new CheckoutPage(page)); },
});

test.use({ storageState: 'playwright/.auth/user.json' });
test('updates profile', async ({ page }, testInfo) => {
  const email = `user-${testInfo.workerIndex}-${crypto.randomUUID()}@example.test`;
});

await page.route('**/api/recommendations', route => route.fulfill({
  status: 200, contentType: 'application/json', body: JSON.stringify([]),
}));
const response = await page.waitForResponse(r => r.url().endsWith('/api/orders') && r.request().method() === 'POST');
expect(response.ok()).toBeTruthy();

const downloadPromise = page.waitForEvent('download');
await page.getByRole('button', { name: 'Export' }).click();
const download = await downloadPromise;
await download.saveAs(testInfo.outputPath(download.suggestedFilename()));

test('expires a session', async ({ page, clock }) => {
  await clock.install({ time: new Date('2026-07-01T00:00:00Z') });
  await test.step('sign in', async () => signIn(page));
  await clock.fastForward('31:00');
  await expect(page.getByRole('heading', { name: 'Sign in' })).toBeVisible();
});
